        self.val = val
        self.left = left
        self.right = right

def imgMultiply(root):
    MOD = 10**9 + 7

    def traverse_tree(node):
        if not node:
            return []
        return traverse_tree(node.left) + [node] + traverse_tree(node.right)

    def traverse_mirror_tree(node):
        if not node:
            return []
